fn actor_thread(
    request: SyncRuntimeOpenRequest,
    advisory: LocalActiveAdvisory,
    session_id: SessionId,
    receiver: Receiver<ActorRequest>,
    started: SyncSender<ActorStartupEvent>,
    shared_status: &RwLock<SyncRuntimeStatusSnapshot>,
) {
    let phases = started.clone();
    let actor = match RuntimeActor::open(request, advisory, session_id, |phase| {
        let _ = phases.send(ActorStartupEvent::Phase(phase));
    }) {
        Ok(actor) => actor,
        Err(error) => {
            let _ = started.send(ActorStartupEvent::Finished(Err(error)));
            return;
        }
    };
    run_actor_loop(actor, receiver, started, shared_status);
}

fn actor_thread_from_same_process_activation(
    request: SyncRuntimeOpenRequest,
    handoff: SameProcessActivationHandoff,
    receiver: Receiver<ActorRequest>,
    started: SyncSender<ActorStartupEvent>,
    shared_status: &RwLock<SyncRuntimeStatusSnapshot>,
) {
    let actor = match RuntimeActor::open_from_same_process_activation(request, handoff) {
        Ok(actor) => actor,
        Err(error) => {
            let _ = started.send(ActorStartupEvent::Finished(Err(error)));
            return;
        }
    };
    run_actor_loop(actor, receiver, started, shared_status);
}

fn run_actor_loop(
    mut actor: RuntimeActor,
    receiver: Receiver<ActorRequest>,
    started: SyncSender<ActorStartupEvent>,
    shared_status: &RwLock<SyncRuntimeStatusSnapshot>,
) {
    let snapshot = actor.snapshot();
    *shared_status.write().unwrap() = snapshot.clone();
    if started
        .send(ActorStartupEvent::Finished(Ok(snapshot)))
        .is_err()
    {
        return;
    }

    while let Ok(request) = receiver.recv() {
        let should_stop = match request {
            ActorRequest::Query { request, reply } => {
                let result = actor.query(request);
                let _ = reply.send(result);
                false
            }
            ActorRequest::ApplicationPageInventory { reply } => {
                let result = actor.application_page_inventory();
                let _ = reply.send(result);
                false
            }
            ActorRequest::LoadApplicationPage { request, reply } => {
                let result = actor.load_application_page(request);
                let _ = reply.send(result);
                false
            }
            ActorRequest::SaveApplicationPage { request, reply } => {
                let result = actor.save_application_page(request);
                let _ = reply.send(result);
                false
            }
            ActorRequest::LoadEditorPage { request, reply } => {
                let result = actor.load_editor_page(request);
                let _ = reply.send(result);
                false
            }
            ActorRequest::SaveEditorPage { request, reply } => {
                let result = actor.save_editor_page(request);
                let _ = reply.send(result);
                false
            }
            ActorRequest::Observe {
                observations,
                reply,
            } => {
                actor.advance_local_mutation_once();
                let result = actor.observe(observations);
                let _ = reply.send(result);
                false
            }
            ActorRequest::ObserveProvider {
                paths,
                imprecise,
                reply,
            } => {
                let result = actor.observe_provider(paths, imprecise);
                let _ = reply.send(result);
                false
            }
            ActorRequest::SubmitLocalMutation { transaction, reply } => {
                let result = actor.submit_local_mutation(transaction);
                let _ = reply.send(result);
                false
            }
            ActorRequest::PrepareShared { reply } => {
                let result = actor.prepare_shared();
                let should_stop = result.is_ok();
                let _ = reply.send(result);
                should_stop
            }
            ActorRequest::JoinShared { descriptor, reply } => {
                let result = actor.join_shared(descriptor);
                let should_stop = matches!(result, Ok(SharedJoinStep::Complete(_)));
                if result.is_err() {
                    // A cursor has already consumed the path that produced the
                    // refusal. The next explicit join attempt must start a
                    // fresh full cut so malformed or transient provider
                    // evidence cannot be skipped by retrying the same actor.
                    actor.pending_join = None;
                }
                let _ = reply.send(result);
                should_stop
            }
            ActorRequest::Tick { reply } => {
                let result = actor.tick();
                let _ = reply.send(result);
                false
            }
            ActorRequest::Status { reply } => {
                actor.advance_local_mutation_once();
                let _ = reply.send(actor.snapshot());
                false
            }
            #[cfg(test)]
            ActorRequest::EngineInstrumentation { reply } => {
                let instrumentation = actor
                    .runtime
                    .as_ref()
                    .expect("active test actor retains its promoted runtime")
                    .engine()
                    .instrumentation();
                let _ = reply.send(instrumentation);
                false
            }
            #[cfg(test)]
            ActorRequest::TickProviderForTest { reply } => {
                if !actor.provider_has_work()
                    && actor.provider_accepted_manifest_revalidation_ready
                    && actor.provider_accepted_manifest_audit.is_none()
                {
                    if let Err(error) = actor.begin_provider_accepted_manifest_revalidation() {
                        let _ = reply.send(SyncRuntimeTick::RecoveryBlocked(error.to_string()));
                        *shared_status.write().unwrap() = actor.snapshot();
                        continue;
                    }
                }
                let result = actor.tick_provider();
                let _ = reply.send(result);
                false
            }
            #[cfg(test)]
            ActorRequest::InstallRepeatedOperationalFault {
                point,
                failures,
                reply,
            } => {
                fail_repeatedly_at(point, failures);
                let _ = reply.send(());
                false
            }
            #[cfg(test)]
            ActorRequest::InstallPendingPublicationMarkerCreationFault { reply } => {
                fail_next_pending_publication_marker_creation();
                let _ = reply.send(());
                false
            }
            #[cfg(test)]
            ActorRequest::InstallProviderPublicationAfterPhysicalWriteFault { reply } => {
                fail_next_provider_publication_after_physical_write();
                let _ = reply.send(());
                false
            }
            ActorRequest::CleanShutdown { reply } => match actor.clean_shutdown() {
                Ok(outcome) => {
                    let _ = reply.send(Ok(outcome));
                    true
                }
                Err(error) => {
                    let _ = reply.send(Err(error));
                    false
                }
            },
        };
        *shared_status.write().unwrap() = actor.snapshot();
        if should_stop {
            break;
        }
    }
}

