    fn admit_external_page(
        handle: &SyncRuntimeHandle,
        fixture: &RuntimeHostFixture,
        path: &str,
        body: &[u8],
    ) {
        let file = fixture.graph_root().join(path);
        fs::create_dir_all(file.parent().unwrap()).unwrap();
        fs::write(file, body).unwrap();
        handle
            .observe_watcher(vec![SyncWatcherObservation::managed_path(path).unwrap()])
            .unwrap();
        settle_exact_feed(handle)
            .unwrap_or_else(|state| panic!("external page {path:?} did not settle: {state:?}"));
    }

    fn load_editor_named(
        handle: &SyncRuntimeHandle,
        name: &str,
        page_kind: SyncPageKind,
    ) -> SyncEditablePageDto {
        match handle
            .load_editor_page(SyncEditorLoadRequest {
                page: SyncEditorPageSelector::Name {
                    name: name.into(),
                    page_kind,
                },
            })
            .unwrap()
        {
            SyncEditorLoadOutcome::Loaded { page } => page,
            other => panic!("editor page did not load: {other:?}"),
        }
    }

    fn block_named(page: &SyncEditablePageDto, needle: &str) -> SyncEditorBlockDto {
        page.blocks
            .iter()
            .find(|block| block.content.contains(needle))
            .cloned()
            .unwrap_or_else(|| panic!("missing editor block containing {needle:?}: {page:?}"))
    }

    fn load_editor_id(handle: &SyncRuntimeHandle, page_id: PageId) -> SyncEditablePageDto {
        match handle
            .load_editor_page(SyncEditorLoadRequest {
                page: SyncEditorPageSelector::PageId {
                    page_id: page_id.to_string(),
                },
            })
            .unwrap()
        {
            SyncEditorLoadOutcome::Loaded { page } => page,
            other => panic!("editor page ID did not load: {other:?}"),
        }
    }

    fn load_application_exact(handle: &SyncRuntimeHandle, path: &str) -> (PageDto, String) {
        match handle
            .load_application_page(SyncApplicationPageLoadRequest {
                page: SyncApplicationPageSelector::ExactPath { path: path.into() },
            })
            .unwrap_or_else(|error| panic!("application page {path:?} failed: {error:?}"))
        {
            SyncApplicationPageLoadOutcome::Loaded { page, revision } => (page, revision),
            other => panic!("application page did not load: {other:?}"),
        }
    }

    fn load_application_logical(
        handle: &SyncRuntimeHandle,
        name: &str,
        page_kind: SyncPageKind,
    ) -> (PageDto, String) {
        match handle
            .load_application_page(SyncApplicationPageLoadRequest {
                page: SyncApplicationPageSelector::Logical {
                    name: name.into(),
                    page_kind,
                },
            })
            .unwrap()
        {
            SyncApplicationPageLoadOutcome::Loaded { page, revision } => (page, revision),
            other => panic!("application page did not load: {other:?}"),
        }
    }

    fn erase_application_block_ids(blocks: &mut [BlockDto]) {
        for block in blocks {
            block.id = "<identity>".into();
            erase_application_block_ids(&mut block.children);
        }
    }

    fn assert_parser_dto_semantics(expected: &PageDto, actual: &PageDto) {
        let mut expected = expected.clone();
        let mut actual = actual.clone();
        erase_application_block_ids(&mut expected.blocks);
        erase_application_block_ids(&mut actual.blocks);
        assert_eq!(
            serde_json::to_value(expected).unwrap(),
            serde_json::to_value(actual).unwrap()
        );
    }

    fn accepted_application_save(
        handle: &SyncRuntimeHandle,
        outcome: SyncApplicationPageSaveOutcome,
        name: &str,
        page_kind: SyncPageKind,
    ) -> (PageDto, String) {
        match outcome {
            SyncApplicationPageSaveOutcome::Saved { page, revision, .. }
            | SyncApplicationPageSaveOutcome::Unchanged { page, revision } => (page, revision),
            SyncApplicationPageSaveOutcome::Deferred {
                state: SyncEditorDeferred::RetryableRetainedPublication { .. },
            } => {
                settle_local_mutation(handle);
                load_application_logical(handle, name, page_kind)
            }
            other => panic!("application save was not accepted: {other:?}"),
        }
    }

    fn new_application_page(
        name: &str,
        page_kind: SyncPageKind,
        pre_block: Option<&str>,
        blocks: Vec<BlockDto>,
    ) -> PageDto {
        PageDto {
            name: name.into(),
            kind: sync_model_page_kind(page_kind),
            title: name.into(),
            pre_block: pre_block.map(str::to_owned),
            blocks,
            rev: None,
            format: Format::Md,
            read_only: false,
            path: String::new(),
            guide: false,
        }
    }

    #[test]
    fn application_gateway_inventory_and_loads_are_parser_owned_with_safe_block_identity() {
        let fixture = RuntimeHostFixture::safe("sync-runtime-application-parser-gateway");
        let request = fixture.request();
        let database_path = request.database_path.clone();
        let handle = active_handle(SyncRuntimeHandle::open(request));
        drive_initial_feed(&handle);
        let genuine = "7f46e275-4f95-4f58-a485-bb8e16726c42";
        admit_external_page(
            &handle,
            &fixture,
            "content/nested pages/Ordinary Ω.md",
            format!(
                "title:: Ordinary Ω\nicon:: 🧭\n\n- TODO [#A] parent #gateway\n  collapsed:: true\n  id:: {genuine}\n  custom:: value\n  - child λ\n"
            )
            .as_bytes(),
        );
        admit_external_page(
            &handle,
            &fixture,
            "diary/日記/2026_07_30.org",
            b"* TODO journal root\n** journal child\n",
        );
        let inventory = match handle.application_page_inventory().unwrap() {
            SyncApplicationPageInventoryOutcome::Loaded { pages } => pages,
            other => panic!("application inventory was not ready: {other:?}"),
        };
        let inventory_semantics = inventory
            .iter()
            .map(|entry| {
                (
                    entry.rel_path.clone(),
                    entry.name.clone(),
                    entry.kind,
                    entry.date_key,
                )
            })
            .collect::<Vec<_>>();
        assert!(inventory_semantics
            .iter()
            .any(|(path, name, kind, date_key)| {
                path == "content/nested pages/Ordinary Ω.md"
                    && name == "Ordinary Ω"
                    && *kind == PageKind::Page
                    && date_key.is_none()
            }));
        assert!(inventory_semantics.iter().any(|(path, _, kind, date_key)| {
            path == "diary/日記/2026_07_30.org" && *kind == PageKind::Journal && date_key.is_some()
        }));

        let graph = Graph::open(fixture.graph_root());
        for path in [
            "content/nested pages/Ordinary Ω.md",
            "diary/日記/2026_07_30.org",
        ] {
            let expected = graph.load_by_path(path).unwrap().unwrap();
            let (actual, _) = load_application_exact(&handle, path);
            assert_parser_dto_semantics(&expected, &actual);
        }
        let (ordinary, _) = load_application_exact(&handle, "content/nested pages/Ordinary Ω.md");
        assert_eq!(ordinary.blocks[0].id, genuine);
        assert_eq!(
            Uuid::parse_str(&ordinary.blocks[0].id).unwrap().to_string(),
            genuine
        );
        assert!(ordinary.blocks[0].children[0]
            .id
            .starts_with(SYNC_APPLICATION_INTERNAL_BLOCK_PREFIX));
        assert!(Uuid::parse_str(&ordinary.blocks[0].children[0].id).is_err());
        assert!(ordinary.blocks[0].collapsed);
        assert_eq!(ordinary.blocks[0].marker.as_deref(), Some("TODO"));
        assert_eq!(ordinary.blocks[0].priority.as_deref(), Some("A"));
        assert!(ordinary.blocks[0].tags.iter().any(|tag| tag == "gateway"));
        assert!(ordinary.blocks[0]
            .properties
            .iter()
            .any(|(name, value)| name == "custom" && value == "value"));

        let connection = rusqlite::Connection::open(database_path).unwrap();
        connection
            .execute(
                "UPDATE pages SET preamble = ?1 WHERE path = ?2",
                rusqlite::params![
                    "counterfeit unrelated inventory row",
                    "diary/日記/2026_07_30.org"
                ],
            )
            .unwrap();
        assert!(matches!(
            handle.application_page_inventory(),
            Err(SyncApplicationPageRequestError::ActorRefused)
        ));
        let (logical, _) = load_application_logical(&handle, " /ORDINARY Ω/ ", SyncPageKind::Page);
        assert_parser_dto_semantics(&ordinary, &logical);
        connection
            .execute(
                "UPDATE pages SET preamble = NULL WHERE path = ?1",
                ["diary/日記/2026_07_30.org"],
            )
            .unwrap();
        drop(connection);
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    #[test]
    fn application_gateway_join_preserves_parser_read_only_org() {
        let root = std::env::temp_dir().join(format!(
            "tine-sync-runtime-read-only-gateway-{}",
            Uuid::new_v4()
        ));
        fs::create_dir_all(root.join("pages")).unwrap();
        fs::write(root.join("pages/Read Only.org"), b"* root\n*** child\n").unwrap();
        let graph = Graph::open(&root);
        let parsed = graph.load_by_path("pages/Read Only.org").unwrap().unwrap();
        assert!(parsed.read_only);
        let flattened = flatten_application_blocks(&parsed.blocks);
        let page_id = PageId::from_uuid(Uuid::from_u128(0x7710));
        let home_document_id = DocumentId::from_uuid(Uuid::from_u128(0x7711));
        let block_ids = (0..flattened.len())
            .map(|index| BlockId::from_uuid(Uuid::from_u128(0x7720 + index as u128)))
            .collect::<Vec<_>>();
        let blocks = flattened
            .iter()
            .enumerate()
            .map(|(index, block)| MaterializedBlock {
                block_id: block_ids[index],
                home_document_id,
                parent: block.parent.map(|parent| block_ids[parent]),
                order: crate::oplog::import::imported_order(index as u32),
                logseq_uuid: None,
                logseq_identity_origin: None,
                content: block.block.raw.clone(),
            })
            .collect::<Vec<_>>();
        let materialized = MaterializedPage {
            page_id,
            home_document_id,
            name: LogicalPageName::parse(parsed.name.clone()).unwrap(),
            path: ManagedPath::parse(parsed.path.clone()).unwrap(),
            kind: ManagedTextKind::Page,
            preamble: parsed.pre_block.clone(),
            blocks: blocks.clone(),
            stats: crate::oplog::MaterializationStats::default(),
        };
        let mut dto = SyncEditablePageDto {
            page_id: page_id.to_string(),
            name: parsed.name.clone(),
            path: parsed.path.clone(),
            page_kind: SyncPageKind::Page,
            preamble: parsed.pre_block.clone(),
            blocks: blocks
                .iter()
                .enumerate()
                .map(|(index, block)| SyncEditorBlockDto {
                    key: SyncEditorBlockKey::Existing(block.block_id.to_string()),
                    parent: flattened[index]
                        .parent
                        .map(|parent| SyncEditorBlockKey::Existing(block_ids[parent].to_string())),
                    content: block.content.clone(),
                })
                .collect(),
            revision: String::new(),
        };
        dto.revision = existing_editor_revision(&materialized, &dto).unwrap();
        let joined = join_application_page(
            parsed,
            EditorCurrentPage {
                page: materialized,
                blocks,
                dto,
            },
        )
        .unwrap();
        assert!(joined.page.read_only);
        assert!(joined
            .page
            .blocks
            .iter()
            .all(|block| block.id.starts_with(SYNC_APPLICATION_INTERNAL_BLOCK_PREFIX)));
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn application_gateway_saves_remap_new_ids_and_use_page_local_revisions() {
        let fixture = RuntimeHostFixture::safe("sync-runtime-application-save-gateway");
        let handle = active_handle(SyncRuntimeHandle::open(fixture.request()));
        drive_initial_feed(&handle);
        admit_external_page(
            &handle,
            &fixture,
            "content/nested pages/Alpha.md",
            b"- alpha root\n  - alpha child\n- delete me\n",
        );
        admit_external_page(
            &handle,
            &fixture,
            "content/nested pages/Beta.md",
            b"- beta original\n",
        );

        let (mut alpha, alpha_revision) =
            load_application_logical(&handle, "Alpha", SyncPageKind::Page);
        assert!(alpha.rev.is_some());
        alpha.rev = None;
        let stale_alpha_revision = alpha_revision.clone();
        let stale_alpha = alpha.clone();
        let (mut beta, beta_revision) =
            load_application_logical(&handle, "Beta", SyncPageKind::Page);
        beta.blocks[0].raw = "beta unrelated edit".into();
        let _ = accepted_application_save(
            &handle,
            handle
                .save_application_page(SyncApplicationPageSaveRequest {
                    target: SyncApplicationPageSaveTarget::Existing {
                        path: beta.path.clone(),
                        revision: beta_revision,
                    },
                    page: beta,
                })
                .unwrap(),
            "Beta",
            SyncPageKind::Page,
        );

        let mut child = alpha.blocks[0].children.remove(0);
        child.children.push(BlockDto {
            id: "arbitrary frontend\nidentity".into(),
            raw: "inserted nested".into(),
            ..BlockDto::default()
        });
        alpha.blocks = vec![child, alpha.blocks.remove(0)];
        let saved_alpha = accepted_application_save(
            &handle,
            handle
                .save_application_page(SyncApplicationPageSaveRequest {
                    target: SyncApplicationPageSaveTarget::Existing {
                        path: alpha.path.clone(),
                        revision: alpha_revision,
                    },
                    page: alpha,
                })
                .unwrap(),
            "Alpha",
            SyncPageKind::Page,
        );
        assert_eq!(saved_alpha.0.blocks.len(), 2);
        assert_eq!(saved_alpha.0.blocks[0].raw, "alpha child");
        assert_eq!(saved_alpha.0.blocks[0].children[0].raw, "inserted nested");
        assert!(saved_alpha.0.blocks[0].children[0]
            .id
            .starts_with(SYNC_APPLICATION_INTERNAL_BLOCK_PREFIX));
        assert_ne!(
            saved_alpha.0.blocks[0].children[0].id,
            "arbitrary frontend\nidentity"
        );
        assert!(matches!(
            handle
                .save_application_page(SyncApplicationPageSaveRequest {
                    target: SyncApplicationPageSaveTarget::Existing {
                        path: saved_alpha.0.path.clone(),
                        revision: saved_alpha.1.clone(),
                    },
                    page: saved_alpha.0.clone(),
                })
                .unwrap(),
            SyncApplicationPageSaveOutcome::Unchanged { .. }
        ));

        let mut stale_alpha = stale_alpha;
        stale_alpha.blocks[0].raw = "must conflict".into();
        assert!(matches!(
            handle
                .save_application_page(SyncApplicationPageSaveRequest {
                    target: SyncApplicationPageSaveTarget::Existing {
                        path: stale_alpha.path.clone(),
                        revision: stale_alpha_revision,
                    },
                    page: stale_alpha,
                })
                .unwrap(),
            SyncApplicationPageSaveOutcome::Conflict {
                reason: SyncApplicationPageConflict::StaleBase
            }
        ));

        let temporary = Uuid::new_v4().to_string();
        let created = accepted_application_save(
            &handle,
            handle
                .save_application_page(SyncApplicationPageSaveRequest {
                    target: SyncApplicationPageSaveTarget::New {
                        name: "Created Ω".into(),
                        page_kind: SyncPageKind::Page,
                    },
                    page: new_application_page(
                        "Created Ω",
                        SyncPageKind::Page,
                        Some("icon:: 🌱"),
                        vec![BlockDto {
                            id: temporary.clone(),
                            raw: "created root".into(),
                            children: vec![BlockDto {
                                id: "any temporary child".into(),
                                raw: "created child".into(),
                                ..BlockDto::default()
                            }],
                            ..BlockDto::default()
                        }],
                    ),
                })
                .unwrap(),
            "Created Ω",
            SyncPageKind::Page,
        );
        assert_ne!(created.0.blocks[0].id, temporary);
        assert!(created.0.blocks[0]
            .id
            .starts_with(SYNC_APPLICATION_INTERNAL_BLOCK_PREFIX));
        assert_eq!(
            load_application_exact(&handle, &created.0.path).1,
            created.1
        );

        admit_external_page(
            &handle,
            &fixture,
            "content/nested pages/Atomic Existing.md",
            b"- existing owner\n",
        );
        let occupied_name = "Atomic Occupied";
        let occupied_path = Graph::open(fixture.graph_root())
            .new_sparse_page_path(occupied_name, PageKind::Page)
            .unwrap();
        admit_external_page(
            &handle,
            &fixture,
            occupied_path.as_str(),
            b"title:: Different Atomic Owner\n\n- occupied path\n",
        );
        let manifests_before = fixture.manifest_count();
        let applied_before = fixture.applied_batch_count();
        let files_before = snapshot_graph_files(fixture.graph_root());
        let status_before = handle.status().unwrap();
        let target = |name: &str| SyncApplicationPageSaveTarget::New {
            name: name.into(),
            page_kind: SyncPageKind::Page,
        };
        for (target, page, reason) in [
            (
                target("Atomic Existing"),
                new_application_page("Atomic Existing", SyncPageKind::Page, None, Vec::new()),
                SyncApplicationPageConflict::PageAlreadyExists,
            ),
            (
                SyncApplicationPageSaveTarget::New {
                    name: "Atomic Existing".into(),
                    page_kind: SyncPageKind::Journal,
                },
                new_application_page("Atomic Existing", SyncPageKind::Journal, None, Vec::new()),
                SyncApplicationPageConflict::AmbiguousPageName,
            ),
            (
                target(occupied_name),
                new_application_page(occupied_name, SyncPageKind::Page, None, Vec::new()),
                SyncApplicationPageConflict::DerivedPathOccupied,
            ),
        ] {
            assert!(matches!(
                handle
                    .save_application_page(SyncApplicationPageSaveRequest { target, page })
                    .unwrap(),
                SyncApplicationPageSaveOutcome::Conflict { reason: actual } if actual == reason
            ));
        }
        let oversized = (0..=MAX_SYNC_EDITOR_BLOCKS)
            .map(|index| BlockDto {
                id: format!("oversized-{index}"),
                raw: "body".into(),
                ..BlockDto::default()
            })
            .collect();
        assert!(matches!(
            handle.save_application_page(SyncApplicationPageSaveRequest {
                target: target("Oversized Gateway"),
                page: new_application_page(
                    "Oversized Gateway",
                    SyncPageKind::Page,
                    None,
                    oversized,
                ),
            }),
            Err(SyncApplicationPageRequestError::RequestTooLarge(_))
        ));
        let mut deep = BlockDto {
            id: "deep-leaf".into(),
            raw: "leaf".into(),
            ..BlockDto::default()
        };
        for depth in 0..MAX_SYNC_EDITOR_DEPTH {
            deep = BlockDto {
                id: format!("deep-{depth}"),
                raw: "parent".into(),
                children: vec![deep],
                ..BlockDto::default()
            };
        }
        assert!(matches!(
            handle.save_application_page(SyncApplicationPageSaveRequest {
                target: target("Deep Gateway"),
                page: new_application_page("Deep Gateway", SyncPageKind::Page, None, vec![deep],),
            }),
            Err(SyncApplicationPageRequestError::RequestTooLarge(_))
        ));
        let duplicate = vec![
            BlockDto {
                id: "duplicate".into(),
                raw: "one".into(),
                ..BlockDto::default()
            },
            BlockDto {
                id: "duplicate".into(),
                raw: "two".into(),
                ..BlockDto::default()
            },
        ];
        assert!(matches!(
            handle.save_application_page(SyncApplicationPageSaveRequest {
                target: target("Malformed Gateway"),
                page: new_application_page(
                    "Malformed Gateway",
                    SyncPageKind::Page,
                    None,
                    duplicate,
                ),
            }),
            Err(SyncApplicationPageRequestError::InvalidRequest(
                SyncApplicationPageInvalidRequest::DuplicateBlockId
            ))
        ));
        assert_eq!(fixture.manifest_count(), manifests_before);
        assert_eq!(fixture.applied_batch_count(), applied_before);
        assert_eq!(snapshot_graph_files(fixture.graph_root()), files_before);
        assert_eq!(handle.status().unwrap(), status_before);
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    #[test]
    fn application_gateway_settles_current_retained_publication_before_returning_saved() {
        let fixture = RuntimeHostFixture::safe("sync-runtime-application-save-settlement");
        let handle = active_handle(SyncRuntimeHandle::open(fixture.request()));
        drive_initial_feed(&handle);
        let existing_path = "content/nested pages/Application Settlement.md";
        admit_external_page(
            &handle,
            &fixture,
            existing_path,
            b"- before application save\n",
        );

        let (mut existing, existing_revision) = load_application_exact(&handle, existing_path);
        existing.blocks[0].raw = "accepted existing application save".into();
        let existing = match handle
            .save_application_page(SyncApplicationPageSaveRequest {
                target: SyncApplicationPageSaveTarget::Existing {
                    path: existing_path.into(),
                    revision: existing_revision,
                },
                page: existing,
            })
            .unwrap()
        {
            SyncApplicationPageSaveOutcome::Saved { page, revision, .. } => (page, revision),
            other => panic!("existing application save was not durable: {other:?}"),
        };
        assert_eq!(
            fs::read(fixture.graph_root().join(existing_path)).unwrap(),
            b"- accepted existing application save\n"
        );
        let existing_reload = load_application_exact(&handle, existing_path);
        assert_parser_dto_semantics(&existing.0, &existing_reload.0);
        assert_eq!(existing.1, existing_reload.1);

        let manifests_before_new = fixture.manifest_count();
        handle
            .install_repeated_operational_fault(OperationalFaultPoint::AfterManifest, 1)
            .unwrap();
        let requested = new_application_page(
            "Created Through Application Ω",
            SyncPageKind::Page,
            Some("icon:: 🌱"),
            vec![BlockDto {
                id: "temporary-created-root".into(),
                raw: "durably created λ".into(),
                ..BlockDto::default()
            }],
        );
        let created = match handle
            .save_application_page(SyncApplicationPageSaveRequest {
                target: SyncApplicationPageSaveTarget::New {
                    name: requested.name.clone(),
                    page_kind: SyncPageKind::Page,
                },
                page: requested,
            })
            .unwrap()
        {
            SyncApplicationPageSaveOutcome::Saved { page, revision, .. } => (page, revision),
            other => panic!("new application save was not durable: {other:?}"),
        };

        assert_eq!(fixture.manifest_count(), manifests_before_new + 1);
        assert_eq!(
            fs::read(fixture.graph_root().join(&created.0.path)).unwrap(),
            "icon:: 🌱\n\n- durably created λ\n".as_bytes()
        );
        let created_reload = load_application_exact(&handle, &created.0.path);
        assert_parser_dto_semantics(&created.0, &created_reload.0);
        assert_eq!(created.1, created_reload.1);
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    #[test]
    fn application_gateway_does_not_admit_request_behind_prior_retained_publication() {
        let fixture = RuntimeHostFixture::safe("sync-runtime-application-prior-publication");
        let handle = active_handle(SyncRuntimeHandle::open(fixture.request()));
        drive_initial_feed(&handle);
        let prior_path = "content/nested pages/Prior Editor Publication.md";
        admit_external_page(
            &handle,
            &fixture,
            prior_path,
            b"- before prior publication\n",
        );
        let prior = load_editor_named(&handle, "Prior Editor Publication", SyncPageKind::Page);
        let mut prior_blocks = prior.blocks.clone();
        prior_blocks[0].content = "settled prior publication".into();
        handle
            .install_repeated_operational_fault(OperationalFaultPoint::AfterStage, 2)
            .unwrap();
        let prior_batch = match handle
            .save_editor_page(SyncEditorSaveRequest {
                target: SyncEditorSaveTarget::Existing {
                    page_id: prior.page_id,
                    revision: prior.revision,
                },
                preamble: prior.preamble,
                blocks: prior_blocks,
            })
            .unwrap()
        {
            SyncEditorSaveOutcome::Deferred {
                state: SyncEditorDeferred::RetryableRetainedPublication { batch_id, .. },
                ..
            } => batch_id,
            other => panic!("low-level editor save did not retain publication: {other:?}"),
        };

        let manifests_after_prior = fixture.manifest_count();
        let requested = new_application_page(
            "Request Behind Prior Publication",
            SyncPageKind::Page,
            None,
            vec![BlockDto {
                id: "temporary-behind-prior".into(),
                raw: "admit exactly once".into(),
                ..BlockDto::default()
            }],
        );
        assert!(matches!(
            handle
                .save_application_page(SyncApplicationPageSaveRequest {
                    target: SyncApplicationPageSaveTarget::New {
                        name: requested.name.clone(),
                        page_kind: SyncPageKind::Page,
                    },
                    page: requested.clone(),
                })
                .unwrap(),
            SyncApplicationPageSaveOutcome::Deferred {
                state: SyncEditorDeferred::RetryableRetainedPublication { batch_id, .. },
            } if batch_id == prior_batch
        ));
        assert_eq!(fixture.manifest_count(), manifests_after_prior);
        let requested_path = Graph::open(fixture.graph_root())
            .new_sparse_page_path(&requested.name, PageKind::Page)
            .unwrap();
        assert!(!fixture.graph_root().join(requested_path.as_str()).exists());

        settle_local_mutation(&handle);
        assert_eq!(
            fs::read(fixture.graph_root().join(prior_path)).unwrap(),
            b"- settled prior publication\n"
        );
        let created = match handle
            .save_application_page(SyncApplicationPageSaveRequest {
                target: SyncApplicationPageSaveTarget::New {
                    name: requested.name.clone(),
                    page_kind: SyncPageKind::Page,
                },
                page: requested,
            })
            .unwrap()
        {
            SyncApplicationPageSaveOutcome::Saved { page, revision, .. } => (page, revision),
            other => panic!("application request was not admitted after prior work: {other:?}"),
        };
        assert_eq!(fixture.manifest_count(), manifests_after_prior + 1);
        assert_eq!(
            fs::read(fixture.graph_root().join(&created.0.path)).unwrap(),
            b"- admit exactly once\n"
        );
        assert_eq!(
            load_application_exact(&handle, &created.0.path).1,
            created.1
        );
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    fn retain_editor_save(handle: &SyncRuntimeHandle, request: SyncEditorSaveRequest) -> PageId {
        let outcome = handle.save_editor_page(request).unwrap();
        let page_id = match &outcome {
            SyncEditorSaveOutcome::Durable { page, .. } => {
                parse_editor_page_id(&page.page_id).unwrap()
            }
            SyncEditorSaveOutcome::Deferred {
                state: SyncEditorDeferred::RetryableRetainedPublication { .. },
                affected_page_ids,
            } => {
                let page_id = parse_editor_page_id(
                    affected_page_ids
                        .first()
                        .expect("retained editor save names its target page"),
                )
                .unwrap();
                settle_local_mutation(handle);
                page_id
            }
            other => panic!("editor save was not retained or durable: {other:?}"),
        };
        page_id
    }

    #[derive(Clone, Copy)]
    struct ExistingEditorIdentityScenario {
        label: &'static str,
        config: Option<&'static [u8]>,
        path: &'static str,
        initial: &'static [u8],
        initial_name: &'static str,
        initial_kind: SyncPageKind,
        requested_preamble: Option<&'static str>,
        expected_name: &'static str,
        expected_kind: SyncPageKind,
    }

    struct EditorIdentityEvidence {
        graph_name: String,
        graph_kind: PageKind,
        replayed_name: String,
        replayed_kind: ManagedTextKind,
        sqlite_name: String,
        sqlite_kind: SyncPageKind,
        sqlite_path: String,
        projection: String,
        restarted: SyncEditablePageDto,
        second_restart: SyncEditablePageDto,
        no_op_reimport_preserved_publication_count: bool,
    }

    fn run_existing_editor_identity_scenario(
        scenario: &ExistingEditorIdentityScenario,
    ) -> EditorIdentityEvidence {
        let open_scenario = |phase, opened: SyncRuntimeOpenResult| {
            assert_eq!(
                opened.status,
                SyncRuntimeOpenStatus::Active,
                "{} {phase} open was refused",
                scenario.label
            );
            opened.handle.expect("active scenario startup has a handle")
        };
        let fixture = match scenario.config {
            Some(config) => RuntimeHostFixture::safe_with_config(scenario.label, config),
            None => RuntimeHostFixture::safe(scenario.label),
        };
        let request = fixture.request();
        fs::create_dir_all(
            fixture
                .graph_root()
                .join(scenario.path)
                .parent()
                .expect("scenario path has a parent"),
        )
        .unwrap();
        let handle = open_scenario("initial", SyncRuntimeHandle::open(request.clone()));
        drive_initial_feed(&handle);
        admit_external_page(&handle, &fixture, scenario.path, scenario.initial);

        let loaded = load_editor_named(&handle, scenario.initial_name, scenario.initial_kind);
        assert_eq!(loaded.path, scenario.path);
        let page_id = retain_editor_save(
            &handle,
            SyncEditorSaveRequest {
                target: SyncEditorSaveTarget::Existing {
                    page_id: loaded.page_id,
                    revision: loaded.revision,
                },
                preamble: scenario.requested_preamble.map(str::to_owned),
                blocks: loaded.blocks,
            },
        );
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
        drop(handle);

        let graph_entry = Graph::open(fixture.graph_root())
            .list_pages()
            .into_iter()
            .find(|entry| entry.rel_path == scenario.path)
            .expect("edited physical path remains present");
        let projection = fs::read_to_string(fixture.graph_root().join(scenario.path)).unwrap();

        let restarted_handle =
            open_scenario("first restart", SyncRuntimeHandle::open(request.clone()));
        drive_initial_feed(&restarted_handle);
        let restarted = load_editor_id(&restarted_handle, page_id);
        let sqlite_page = match restarted_handle
            .query(SyncRuntimeQueryRequest::ListPages {
                page_kind: None,
                limit: MAX_MATERIALIZATION_QUERY_ROWS,
            })
            .unwrap()
        {
            SyncRuntimeQueryReply::Pages(pages) => pages
                .into_iter()
                .find(|page| page.page_id == page_id.to_string())
                .expect("SQLite page list contains the edited page"),
            other => panic!("SQLite page list returned the wrong reply: {other:?}"),
        };
        let manifests_before_noop = fixture.manifest_count();
        restarted_handle
            .observe_watcher(vec![
                SyncWatcherObservation::managed_path(scenario.path).unwrap()
            ])
            .unwrap();
        settle_exact_feed(&restarted_handle)
            .unwrap_or_else(|state| panic!("unchanged reimport did not settle: {state:?}"));
        let no_op_reimport_preserved_publication_count =
            fixture.manifest_count() == manifests_before_noop;
        assert!(matches!(
            restarted_handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
        drop(restarted_handle);

        let second_handle = open_scenario("second restart", SyncRuntimeHandle::open(request));
        drive_initial_feed(&second_handle);
        let second_restart = load_editor_id(&second_handle, page_id);
        assert!(matches!(
            second_handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
        let replayed = fixture.replay_materialized_page(page_id);

        EditorIdentityEvidence {
            graph_name: graph_entry.name,
            graph_kind: graph_entry.kind,
            replayed_name: replayed.name.as_str().to_owned(),
            replayed_kind: replayed.kind,
            sqlite_name: sqlite_page.name,
            sqlite_kind: sqlite_page.kind,
            sqlite_path: sqlite_page.path,
            projection,
            restarted,
            second_restart,
            no_op_reimport_preserved_publication_count,
        }
    }

    fn assert_editor_identity_evidence(
        scenario: &ExistingEditorIdentityScenario,
        evidence: &EditorIdentityEvidence,
    ) {
        let expected_model_kind = sync_model_page_kind(scenario.expected_kind);
        let expected_managed_kind: ManagedTextKind = scenario.expected_kind.into();
        assert_eq!(evidence.graph_name, scenario.expected_name);
        assert_eq!(evidence.graph_kind, expected_model_kind);
        assert_eq!(evidence.replayed_name, scenario.expected_name);
        assert_eq!(evidence.replayed_kind, expected_managed_kind);
        assert_eq!(evidence.sqlite_name, scenario.expected_name);
        assert_eq!(evidence.sqlite_kind, scenario.expected_kind);
        assert_eq!(evidence.sqlite_path, scenario.path);
        assert_eq!(evidence.restarted.name, scenario.expected_name);
        assert_eq!(evidence.restarted.page_kind, scenario.expected_kind);
        assert_eq!(evidence.restarted.path, scenario.path);
        assert_eq!(evidence.second_restart, evidence.restarted);
        assert!(evidence.no_op_reimport_preserved_publication_count);
        if let Some(preamble) = scenario.requested_preamble {
            assert!(
                evidence.projection.contains(preamble),
                "projection does not contain the requested parser-owned preamble: {:?}",
                evidence.projection
            );
        }
    }

    struct NewEditorIdentityScenario {
        label: &'static str,
        config: &'static [u8],
        draft_name: &'static str,
        draft_kind: SyncPageKind,
        preamble: &'static str,
        expected_name: &'static str,
        expected_kind: SyncPageKind,
        expected_extension: &'static str,
    }

    fn run_new_editor_identity_scenario(
        scenario: &NewEditorIdentityScenario,
    ) -> (
        SyncEditablePageDto,
        crate::model::PageEntry,
        MaterializedPage,
        SyncPageDto,
        String,
    ) {
        let fixture = RuntimeHostFixture::safe_with_config(scenario.label, scenario.config);
        let request = fixture.request();
        let graph = Graph::open(fixture.graph_root());
        let selected_path = graph
            .new_sparse_page_path(
                scenario.draft_name,
                sync_model_page_kind(scenario.draft_kind),
            )
            .unwrap();
        let handle = active_handle(SyncRuntimeHandle::open(request.clone()));
        drive_initial_feed(&handle);
        let draft = match handle
            .load_editor_page(SyncEditorLoadRequest {
                page: SyncEditorPageSelector::Name {
                    name: scenario.draft_name.into(),
                    page_kind: scenario.draft_kind,
                },
            })
            .unwrap()
        {
            SyncEditorLoadOutcome::NewPage { draft } => draft,
            other => panic!("new-page scenario did not produce a draft: {other:?}"),
        };
        let page_id = retain_editor_save(
            &handle,
            SyncEditorSaveRequest {
                target: SyncEditorSaveTarget::New {
                    name: draft.name,
                    page_kind: draft.page_kind,
                    revision: draft.revision,
                },
                preamble: Some(scenario.preamble.into()),
                blocks: vec![SyncEditorBlockDto {
                    key: SyncEditorBlockKey::Temporary("body".into()),
                    parent: None,
                    content: "new explicit-title body".into(),
                }],
            },
        );
        let saved = load_editor_id(&handle, page_id);
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
        drop(handle);

        let graph_entry = Graph::open(fixture.graph_root())
            .list_pages()
            .into_iter()
            .find(|entry| entry.rel_path == selected_path.as_str())
            .expect("new editor page retained the actor-selected target path");
        let projection =
            fs::read_to_string(fixture.graph_root().join(selected_path.as_str())).unwrap();
        let restarted = active_handle(SyncRuntimeHandle::open(request));
        drive_initial_feed(&restarted);
        let restarted_page = load_editor_id(&restarted, page_id);
        let sqlite_page = match restarted
            .query(SyncRuntimeQueryRequest::ListPages {
                page_kind: None,
                limit: MAX_MATERIALIZATION_QUERY_ROWS,
            })
            .unwrap()
        {
            SyncRuntimeQueryReply::Pages(pages) => pages
                .into_iter()
                .find(|page| page.page_id == page_id.to_string())
                .expect("SQLite contains the new page"),
            other => panic!("SQLite page list returned the wrong reply: {other:?}"),
        };
        assert!(matches!(
            restarted.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
        let replayed = fixture.replay_materialized_page(page_id);

        assert_eq!(saved, restarted_page);
        assert_eq!(saved.path, selected_path.as_str());
        assert!(saved.path.ends_with(scenario.expected_extension));
        (saved, graph_entry, replayed, sqlite_page, projection)
    }

    #[test]
    fn public_name_lookup_matches_og_names_across_nested_supported_extensions() {
        let fixture = RuntimeHostFixture::safe("sync-runtime-name-query");
        let handle = active_handle(SyncRuntimeHandle::open(fixture.request()));
        drive_initial_feed(&handle);
        let cases = [
            (
                "content/nested pages/Résumé 日本語.md",
                "Résumé 日本語",
                " /RÉSUMÉ 日本語/ ",
            ),
            (
                "content/nested pages/Long Name.markdown",
                "Long Name",
                "long name",
            ),
            (
                "content/nested pages/Überblick.org",
                "Überblick",
                "ÜBERBLICK",
            ),
        ];
        for (path, _, _) in cases {
            admit_external_page(&handle, &fixture, path, b"- body\n");
        }
        for (path, expected_name, query_name) in cases {
            let request = SyncRuntimeQueryRequest::ResolvePageByName {
                name: query_name.into(),
                page_kind: SyncPageKind::Page,
            };
            assert_eq!(
                serde_json::from_slice::<SyncRuntimeQueryRequest>(
                    &serde_json::to_vec(&request).unwrap()
                )
                .unwrap(),
                request
            );
            let reply = handle.query(request).unwrap();
            assert_eq!(
                serde_json::from_slice::<SyncRuntimeQueryReply>(
                    &serde_json::to_vec(&reply).unwrap()
                )
                .unwrap(),
                reply
            );
            let SyncRuntimeQueryReply::PageName(SyncPageNameResolutionDto::Exact { page }) = reply
            else {
                panic!("name query did not return one exact owner: {reply:?}");
            };
            assert_eq!(page.path, path);
            assert_eq!(page.name, expected_name);
        }
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    #[test]
    fn sqlite_name_counterfeit_cannot_authorize_or_block_editor_name_mutations() {
        let fixture = RuntimeHostFixture::safe("sync-runtime-name-ambiguity");
        let request = fixture.request();
        let database_path = request.database_path.clone();
        let handle = active_handle(SyncRuntimeHandle::open(request));
        drive_initial_feed(&handle);
        let path = "content/nested pages/Duplicate Owner.md";
        admit_external_page(&handle, &fixture, path, b"- first owner\n");

        let genuine = load_editor_named(&handle, "Duplicate Owner", SyncPageKind::Page);
        let genuine_page = Uuid::parse_str(&genuine.page_id).unwrap();
        let counterfeit_pages = [
            Uuid::from_u128(0x11),
            Uuid::from_u128(0x12),
            Uuid::from_u128(0x13),
            Uuid::from_u128(0x14),
        ];
        assert!(counterfeit_pages
            .iter()
            .all(|page_id| page_id.as_bytes() < genuine_page.as_bytes()));
        let connection = rusqlite::Connection::open(&database_path).unwrap();
        let insert_counterfeit =
            |page_id: Uuid, home_id: Uuid, name: &str, name_key: &str, counterfeit_path: &str| {
                connection
                    .execute(
                        "INSERT INTO pages(
                    page_id, home_document_id, name, name_key, path,
                    text_kind, preamble, searchable_text
                 )
                 SELECT ?1, ?2, ?3, ?4, ?5,
                        text_kind, preamble, searchable_text
                 FROM pages WHERE path = ?6",
                        rusqlite::params![
                            page_id.as_bytes().as_slice(),
                            home_id.as_bytes().as_slice(),
                            name,
                            name_key,
                            counterfeit_path,
                            path,
                        ],
                    )
                    .unwrap();
            };
        let duplicate_name = LogicalPageName::parse("Duplicate Owner").unwrap();
        for (page_id, home_id, counterfeit_path) in [
            (
                counterfeit_pages[0],
                Uuid::from_u128(0x21),
                "other/nonstandard/duplicate-one.markdown",
            ),
            (
                counterfeit_pages[1],
                Uuid::from_u128(0x22),
                "other/nonstandard/duplicate-two.markdown",
            ),
        ] {
            insert_counterfeit(
                page_id,
                home_id,
                duplicate_name.as_str(),
                &duplicate_name.canonical_key(),
                counterfeit_path,
            );
        }
        let absent_name = LogicalPageName::parse("Authenticated Absent").unwrap();
        for (page_id, home_id, counterfeit_path) in [
            (
                counterfeit_pages[2],
                Uuid::from_u128(0x23),
                "other/nonstandard/absent-one.markdown",
            ),
            (
                counterfeit_pages[3],
                Uuid::from_u128(0x24),
                "other/nonstandard/absent-two.markdown",
            ),
        ] {
            insert_counterfeit(
                page_id,
                home_id,
                absent_name.as_str(),
                &absent_name.canonical_key(),
                counterfeit_path,
            );
        }

        assert_eq!(
            handle
                .query(SyncRuntimeQueryRequest::ResolvePageByName {
                    name: " duplicate owner ".into(),
                    page_kind: SyncPageKind::Page,
                })
                .unwrap(),
            SyncRuntimeQueryReply::PageName(SyncPageNameResolutionDto::Ambiguous)
        );
        let loaded = load_editor_named(&handle, "Duplicate Owner", SyncPageKind::Page);
        assert_eq!(loaded.path, path);
        assert_eq!(loaded.blocks[0].content, "first owner");
        let (application, _) = load_application_exact(&handle, path);
        assert_eq!(application.path, path);
        assert_eq!(application.blocks[0].raw, "first owner");
        let manifests_before = fixture.manifest_count();
        let applied_before = fixture.applied_batch_count();
        let files_before = snapshot_graph_files(fixture.graph_root());
        let status_before = handle.status().unwrap();
        assert_eq!(
            handle
                .save_editor_page(SyncEditorSaveRequest {
                    target: SyncEditorSaveTarget::New {
                        name: "Duplicate Owner".into(),
                        page_kind: SyncPageKind::Page,
                        revision: "opaque-stale-draft".into(),
                    },
                    preamble: None,
                    blocks: Vec::new(),
                })
                .unwrap(),
            SyncEditorSaveOutcome::Conflict {
                reason: SyncEditorConflict::PageAlreadyExists
            }
        );
        assert_eq!(fixture.manifest_count(), manifests_before);
        assert_eq!(fixture.applied_batch_count(), applied_before);
        assert_eq!(snapshot_graph_files(fixture.graph_root()), files_before);
        assert_eq!(handle.status().unwrap(), status_before);

        let draft = match handle
            .load_editor_page(SyncEditorLoadRequest {
                page: SyncEditorPageSelector::Name {
                    name: absent_name.as_str().into(),
                    page_kind: SyncPageKind::Page,
                },
            })
            .unwrap()
        {
            SyncEditorLoadOutcome::NewPage { draft } => draft,
            other => panic!("authenticated-absent name was hidden by counterfeit rows: {other:?}"),
        };
        let saved = handle
            .save_editor_page(SyncEditorSaveRequest {
                target: SyncEditorSaveTarget::New {
                    name: draft.name,
                    page_kind: draft.page_kind,
                    revision: draft.revision,
                },
                preamble: None,
                blocks: vec![SyncEditorBlockDto {
                    key: SyncEditorBlockKey::Temporary("legitimate-root".into()),
                    parent: None,
                    content: "authenticated absence permits creation".into(),
                }],
            })
            .unwrap();
        assert!(
            matches!(saved, SyncEditorSaveOutcome::Durable { .. }),
            "authenticated absence did not permit the legitimate mutation: {saved:?}"
        );

        connection
            .execute(
                "DELETE FROM pages WHERE page_id IN (?1, ?2, ?3, ?4)",
                rusqlite::params![
                    counterfeit_pages[0].as_bytes().as_slice(),
                    counterfeit_pages[1].as_bytes().as_slice(),
                    counterfeit_pages[2].as_bytes().as_slice(),
                    counterfeit_pages[3].as_bytes().as_slice(),
                ],
            )
            .unwrap();
        drop(connection);
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    #[test]
    fn authenticated_path_owner_blocks_new_editor_page_when_sqlite_hides_it() {
        let fixture = RuntimeHostFixture::safe("sync-runtime-editor-path-authority");
        let request = fixture.request();
        let database_path = request.database_path.clone();
        let handle = active_handle(SyncRuntimeHandle::open(request));
        drive_initial_feed(&handle);

        let draft = match handle
            .load_editor_page(SyncEditorLoadRequest {
                page: SyncEditorPageSelector::Name {
                    name: "Derived Occupied".into(),
                    page_kind: SyncPageKind::Page,
                },
            })
            .unwrap()
        {
            SyncEditorLoadOutcome::NewPage { draft } => draft,
            other => panic!("missing name did not produce an editor draft: {other:?}"),
        };
        let derived_path = Graph::open(fixture.graph_root())
            .new_sparse_page_path("Derived Occupied", PageKind::Page)
            .unwrap();
        admit_external_page(
            &handle,
            &fixture,
            derived_path.as_str(),
            b"title:: Different Owner\n\n- path owner\n",
        );
        let owner = load_editor_named(&handle, "Different Owner", SyncPageKind::Page);
        assert_eq!(owner.path, derived_path.as_str());

        let connection = rusqlite::Connection::open(&database_path).unwrap();
        connection
            .execute(
                "UPDATE pages SET path = ?1 WHERE page_id = ?2",
                rusqlite::params![
                    "counterfeit/hidden-owner.md",
                    Uuid::parse_str(&owner.page_id)
                        .unwrap()
                        .as_bytes()
                        .as_slice(),
                ],
            )
            .unwrap();
        assert_eq!(
            handle
                .load_editor_page(SyncEditorLoadRequest {
                    page: SyncEditorPageSelector::Name {
                        name: draft.name.clone(),
                        page_kind: draft.page_kind,
                    },
                })
                .unwrap(),
            SyncEditorLoadOutcome::AmbiguousPageName
        );
        assert_eq!(
            handle
                .save_editor_page(SyncEditorSaveRequest {
                    target: SyncEditorSaveTarget::New {
                        name: draft.name,
                        page_kind: draft.page_kind,
                        revision: draft.revision,
                    },
                    preamble: None,
                    blocks: Vec::new(),
                })
                .unwrap(),
            SyncEditorSaveOutcome::Conflict {
                reason: SyncEditorConflict::DerivedPathOccupied
            }
        );
        connection
            .execute(
                "UPDATE pages SET path = ?1 WHERE page_id = ?2",
                rusqlite::params![
                    derived_path.as_str(),
                    Uuid::parse_str(&owner.page_id)
                        .unwrap()
                        .as_bytes()
                        .as_slice(),
                ],
            )
            .unwrap();
        drop(connection);
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    #[test]
    fn editor_intent_creates_page_and_journal_with_actor_owned_identity_and_order() {
        let fixture = RuntimeHostFixture::safe("sync-runtime-editor-create");
        let handle = active_handle(SyncRuntimeHandle::open(fixture.request()));
        drive_initial_feed(&handle);

        for (name, page_kind) in [
            ("Actor Created", SyncPageKind::Page),
            ("Jul 28th, 2026", SyncPageKind::Journal),
        ] {
            let draft = match handle
                .load_editor_page(SyncEditorLoadRequest {
                    page: SyncEditorPageSelector::Name {
                        name: name.into(),
                        page_kind,
                    },
                })
                .unwrap()
            {
                SyncEditorLoadOutcome::NewPage { draft } => draft,
                other => panic!("missing page did not return a creation draft: {other:?}"),
            };
            let request = SyncEditorSaveRequest {
                target: SyncEditorSaveTarget::New {
                    name: draft.name,
                    page_kind: draft.page_kind,
                    revision: draft.revision,
                },
                preamble: Some("created:: by actor".into()),
                blocks: vec![
                    SyncEditorBlockDto {
                        key: SyncEditorBlockKey::Temporary("root".into()),
                        parent: None,
                        content: "new root".into(),
                    },
                    SyncEditorBlockDto {
                        key: SyncEditorBlockKey::Temporary("child".into()),
                        parent: Some(SyncEditorBlockKey::Temporary("root".into())),
                        content: "new child".into(),
                    },
                ],
            };
            let encoded = serde_json::to_vec(&request).unwrap();
            assert_eq!(
                serde_json::from_slice::<SyncEditorSaveRequest>(&encoded).unwrap(),
                request
            );
            let saved = handle.save_editor_page(request).unwrap();
            assert_eq!(
                serde_json::from_slice::<SyncEditorSaveOutcome>(
                    &serde_json::to_vec(&saved).unwrap()
                )
                .unwrap(),
                saved
            );
            let SyncEditorSaveOutcome::Durable {
                page,
                affected_page_ids,
                ..
            } = saved
            else {
                panic!("new editor page was not durable: {saved:?}");
            };
            assert_eq!(affected_page_ids, vec![page.page_id.clone()]);
            assert_eq!(page.page_kind, page_kind);
            assert_eq!(page.blocks.len(), 2);
            assert!(page
                .blocks
                .iter()
                .all(|block| matches!(block.key, SyncEditorBlockKey::Existing(_))));
            assert_eq!(page.blocks[1].parent, Some(page.blocks[0].key.clone()));
            assert!(!page.path.is_empty());
            assert!(fixture.graph_root().join(&page.path).is_file());
        }
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

    #[test]
    fn editor_intent_edits_inserts_moves_reorders_and_deletes_nested_outline() {
        let fixture = RuntimeHostFixture::safe("sync-runtime-editor-outline");
        let handle = active_handle(SyncRuntimeHandle::open(fixture.request()));
        drive_initial_feed(&handle);
        let path = "content/nested pages/Editor Intent.md";
        admit_external_page(
            &handle,
            &fixture,
            path,
            b"title:: Editor Intent\n\n- root one\n  - child move\n    - grand delete\n- root two\n  - child keep\n",
        );
        let loaded = load_editor_named(&handle, "Editor Intent", SyncPageKind::Page);
        let mut root_one = block_named(&loaded, "root one");
        let child_move = block_named(&loaded, "child move");
        let root_two = block_named(&loaded, "root two");
        let child_keep = block_named(&loaded, "child keep");
        let deleted = block_named(&loaded, "grand delete").key;
        root_one.content = "root one edited".into();
        let desired = vec![
            SyncEditorBlockDto {
                parent: None,
                ..root_two.clone()
            },
            SyncEditorBlockDto {
                parent: Some(root_two.key.clone()),
                ..child_keep.clone()
            },
            SyncEditorBlockDto {
                key: SyncEditorBlockKey::Temporary("new-top".into()),
                parent: None,
                content: "inserted top".into(),
            },
            SyncEditorBlockDto {
                parent: Some(SyncEditorBlockKey::Temporary("new-top".into())),
                ..child_move.clone()
            },
            SyncEditorBlockDto {
                key: SyncEditorBlockKey::Temporary("new-nested".into()),
                parent: Some(SyncEditorBlockKey::Temporary("new-top".into())),
                content: "inserted nested".into(),
            },
            SyncEditorBlockDto {
                parent: None,
                ..root_one.clone()
            },
        ];
        let saved = handle
            .save_editor_page(SyncEditorSaveRequest {
                target: SyncEditorSaveTarget::Existing {
                    page_id: loaded.page_id.clone(),
                    revision: loaded.revision,
                },
                preamble: Some("title:: Editor Intent\nstatus:: edited".into()),
                blocks: desired,
            })
            .unwrap();
        let page = match saved {
            SyncEditorSaveOutcome::Durable { page, .. } => page,
            SyncEditorSaveOutcome::Deferred {
                state: SyncEditorDeferred::RetryableRetainedPublication { .. },
                ..
            } => {
                settle_local_mutation(&handle);
                load_editor_named(&handle, "Editor Intent", SyncPageKind::Page)
            }
            other => panic!("outline save was not retained or durable: {other:?}"),
        };
        assert_eq!(page.blocks.len(), 6);
        assert!(!page.blocks.iter().any(|block| block.key == deleted));
        assert_eq!(
            page.blocks
                .iter()
                .map(|block| block.content.as_str())
                .collect::<Vec<_>>(),
            vec![
                "root two",
                "child keep",
                "inserted top",
                "child move",
                "inserted nested",
                "root one edited",
            ]
        );
        let inserted_top = block_named(&page, "inserted top");
        assert_eq!(
            block_named(&page, "child move").parent,
            Some(inserted_top.key.clone())
        );
        assert_eq!(
            block_named(&page, "inserted nested").parent,
            Some(inserted_top.key)
        );
        assert_eq!(
            page.preamble.as_deref(),
            Some("title:: Editor Intent\nstatus:: edited")
        );
        let bytes = fs::read_to_string(fixture.graph_root().join(path)).unwrap();
        assert!(bytes.contains("root one edited"));
        assert!(bytes.contains("inserted nested"));
        assert!(!bytes.contains("grand delete"));
        assert!(matches!(
            handle.clean_shutdown().unwrap(),
            SyncShutdownOutcome::Safe(_)
        ));
    }

