        drive_initial_feed(&handle);

        let lease_path = fixture.lease_path();
        let incoming = lease_path.with_extension("lock.incoming");
        fs::write(&incoming, b"").unwrap();
        fs::rename(&incoming, &lease_path).unwrap();
